/// <reference lib="webworker" />

import init, { BrowserRenderer } from "./wasm/engine_sim_web.js";

type RenderRequest = {
  engineId: string;
  seconds: number;
  throttle: number;
};

const scope: DedicatedWorkerGlobalScope = self as unknown as DedicatedWorkerGlobalScope;

scope.addEventListener("message", async (event: MessageEvent<RenderRequest>) => {
  try {
    await init();
    const renderer = new BrowserRenderer(event.data.engineId, event.data.seconds, event.data.throttle);
    const engineName = renderer.engine_name();
    scope.postMessage({
      type: "ready",
      engineName,
      model: {
        fuelName: renderer.fuel_name(),
        cylinderCount: renderer.cylinder_count(),
        cylinderBankCount: renderer.cylinder_bank_count(),
        displacementLiters: renderer.displacement_liters(),
        intakeCount: renderer.intake_count(),
        exhaustCount: renderer.exhaust_count(),
        impulseResponseCount: renderer.impulse_response_count(),
        simulationFrequency: renderer.simulation_frequency(),
        convolutionMix: renderer.convolution_mix(),
      },
    });

    let complete = false;
    while (!complete) {
      complete = renderer.render_chunk(2);
      const samples = renderer.take_audio_chunk();
      if (samples.length > 0) {
        scope.postMessage(
          { type: "audio", samples, sampleRate: renderer.sample_rate() },
          [samples.buffer],
        );
      }
      scope.postMessage({
        type: "progress",
        progress: renderer.progress(),
        telemetry: {
          rpm: renderer.current_rpm(),
          manifoldPressureKpa: renderer.manifold_pressure_kpa(),
          intakeAfr: renderer.intake_afr(),
          cylinderPressureKpa: renderer.mean_cylinder_pressure_kpa(),
          exhaustPressureKpa: renderer.exhaust_pressure_kpa(),
        },
      });
      await new Promise((resolve) => setTimeout(resolve, 0));
    }

    const bytes = renderer.wav_bytes();
    renderer.free();
    scope.postMessage(
      { type: "complete", bytes, engineName, sampleRate: renderer.sample_rate() },
      [bytes.buffer],
    );
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    scope.postMessage({ type: "error", message });
  }
});

export {};
